/// Hey AI brand tokens and the logo mark. See brand/BRAND.md.
enum Brand {
    static let ink = Color(red: 0x1B / 255, green: 0x1A / 255, blue: 0x2E / 255)
    static let paper = Color.white
    static let mist = Color(red: 0xF0 / 255, green: 0xF1 / 255, blue: 0xF6 / 255)
    /// Only for words you say out loud, and the mark on ink.
    static let highlight = Color(red: 0xFF / 255, green: 0xD8 / 255, blue: 0x4D / 255)
    static let signal = Color(red: 0x4B / 255, green: 0x4B / 255, blue: 0xE6 / 255)
    static let graphite = Color(red: 0x5C / 255, green: 0x5B / 255, blue: 0x70 / 255)

    static let nsInk = NSColor(srgbRed: 0x1B / 255, green: 0x1A / 255, blue: 0x2E / 255, alpha: 1)
    static let nsHighlight = NSColor(srgbRed: 0xFF / 255, green: 0xD8 / 255, blue: 0x4D / 255, alpha: 1)
    /// Signal, lightened on dark backgrounds (#9C9CFF), per BRAND.md.
    static let nsSignal = NSColor(name: nil) { appearance in
        appearance.bestMatch(from: [.aqua, .darkAqua]) == .darkAqua
            ? NSColor(srgbRed: 0x9C / 255, green: 0x9C / 255, blue: 0xFF / 255, alpha: 1)
            : NSColor(srgbRed: 0x4B / 255, green: 0x4B / 255, blue: 0xE6 / 255, alpha: 1)
    }

    /// A small Highlight pill with Ink text: how the brand marks a phrase you say, sized
    /// to sit in a menu item.
    static func phrasePill(_ text: String, size: CGFloat = 13) -> NSImage {
        let font = NSFont.systemFont(ofSize: size, weight: .medium)
        let attributes: [NSAttributedString.Key: Any] = [.font: font, .foregroundColor: nsInk]
        let textSize = (text as NSString).size(withAttributes: attributes)
        let pad = CGSize(width: 5, height: 1)
        let pillSize = NSSize(width: ceil(textSize.width + pad.width * 2), height: ceil(textSize.height + pad.height * 2))
        let image = NSImage(size: pillSize, flipped: false) { bounds in
            nsHighlight.setFill()
            NSBezierPath(roundedRect: bounds, xRadius: 4, yRadius: 4).fill()
            (text as NSString).draw(at: NSPoint(x: pad.width, y: pad.height), withAttributes: attributes)
            return true
        }
        image.accessibilityDescription = text
        return image
    }

