    private static let wordmarkBounds = CGRect(x: 69.6, y: -750.0, width: 3755.6, height: 931.4)
    private static let wordmarkOutline: CGPath = SVGPath.parse(wordmarkData)

    /// The mark scaled to fit `rect` (aspect-fit, centered).
    static func markPath(in rect: CGRect) -> CGPath { fit(markOutline, markBounds, in: rect) }

    static func wordmarkPath(in rect: CGRect) -> CGPath { fit(wordmarkOutline, wordmarkBounds, in: rect) }

    /// Width ÷ height of the wordmark, for sizing frames.
    static let wordmarkAspect = wordmarkBounds.width / wordmarkBounds.height

    private static func fit(_ outline: CGPath, _ bounds: CGRect, in rect: CGRect) -> CGPath {
        let scale = min(rect.width / bounds.width, rect.height / bounds.height)
        let w = bounds.width * scale, h = bounds.height * scale
        var t = CGAffineTransform(translationX: rect.midX - w / 2, y: rect.midY - h / 2)
            .scaledBy(x: scale, y: scale)
            .translatedBy(x: -bounds.minX, y: -bounds.minY)
        return outline.copy(using: &t) ?? outline
    }

    enum MenuState { case listening, paused, heard, dictating }

    /// Template image for the menu bar (macOS tints it for light/dark menu bars).
    static func menuBarImage(_ state: MenuState) -> NSImage {
        let size = NSSize(width: 24, height: 16)
        let image = NSImage(size: size, flipped: true) { bounds in
            guard let ctx = NSGraphicsContext.current?.cgContext else { return false }
            ctx.setFillColor(NSColor.black.cgColor)
            switch state {
            case .listening:
                ctx.addPath(markPath(in: bounds.insetBy(dx: 2, dy: 1.5)))
                ctx.fillPath()
            case .paused:
                ctx.setAlpha(0.35)
                ctx.addPath(markPath(in: bounds.insetBy(dx: 2, dy: 1.5)))
                ctx.fillPath()
                ctx.setAlpha(1)
                ctx.setStrokeColor(NSColor.black.cgColor)
                ctx.setLineWidth(1.6)
                ctx.setLineCap(.round)
                ctx.move(to: CGPoint(x: 3, y: 1.5))
                ctx.addLine(to: CGPoint(x: 21, y: 14.5))
                ctx.strokePath()
            case .heard:
                // The mark knocked out of a filled pill: "I heard you".
                let pill = CGPath(roundedRect: bounds.insetBy(dx: 0.5, dy: 0.5), cornerWidth: 5, cornerHeight: 5, transform: nil)
                ctx.addPath(pill)
                ctx.fillPath()
                ctx.setBlendMode(.destinationOut)
                ctx.addPath(markPath(in: bounds.insetBy(dx: 5, dy: 3.5)))
                ctx.fillPath()
            case .dictating:
                // Smaller mark plus a dot: words are going into Claude Code.
                ctx.addPath(markPath(in: CGRect(x: 0.5, y: 2.5, width: 15, height: 11)))
                ctx.fillPath()
                ctx.fillEllipse(in: CGRect(x: 18, y: 9, width: 5, height: 5))
            }
            return true
        }
        image.isTemplate = true
        image.accessibilityDescription = "Hey AI"
        return image
    }
}

/// The mark as a SwiftUI shape.
struct BrandMark: Shape {
    func path(in rect: CGRect) -> Path { Path(Brand.markPath(in: rect)) }
}

/// The "Hey AI" wordmark as a SwiftUI shape.
struct BrandWordmark: Shape {
    func path(in rect: CGRect) -> Path { Path(Brand.wordmarkPath(in: rect)) }
}

/// Minimal SVG path-data reader for the absolute M/L/H/V/Q/C/Z commands fontTools writes,
/// including implicit repeats ("M x y x y" = move, then line).
enum SVGPath {
    static func parse(_ data: String) -> CGPath {
        let path = CGMutablePath()
        var tokens: [String] = []
        var number = ""
        for ch in data {
            if ch.isLetter && ch != "e" {
                if !number.isEmpty { tokens.append(number); number = "" }
                tokens.append(String(ch))
            } else if ch == " " || ch == "," {
                if !number.isEmpty { tokens.append(number); number = "" }
            } else if ch == "-" && !number.isEmpty && number.last != "e" {
                tokens.append(number); number = "-"
            } else {
                number.append(ch)
            }
        }
        if !number.isEmpty { tokens.append(number) }

        var i = 0
        var command = "M"
        var current = CGPoint.zero
        func next() -> CGFloat { defer { i += 1 }; return CGFloat(Double(tokens[i]) ?? 0) }
        func point() -> CGPoint { CGPoint(x: next(), y: next()) }
        while i < tokens.count {
            if let c = tokens[i].first, c.isLetter { command = tokens[i]; i += 1 }
            switch command {
            case "M": current = point(); path.move(to: current); command = "L"
            case "L": current = point(); path.addLine(to: current)
            case "H": current = CGPoint(x: next(), y: current.y); path.addLine(to: current)
            case "V": current = CGPoint(x: current.x, y: next()); path.addLine(to: current)
            case "Q": let c = point(); current = point(); path.addQuadCurve(to: current, control: c)
            case "C": let c1 = point(), c2 = point(); current = point(); path.addCurve(to: current, control1: c1, control2: c2)
            case "Z", "z": path.closeSubpath()
            default: i += 1
            }
        }
        return path
    }
}
